{
  "labels": [
    {
      "i": 0,
      "speaker": "bot",
      "text": "Hello राकेश आपको कश्मीरी organic saffron of hills की requirement है ना?"
    },
    {
      "i": 1,
      "speaker": "caller",
      "text": "हाँ जी।"
    },
    {
      "i": 2,
      "speaker": "bot",
      "text": "ठीक है मैं Tanya बोल रही हूं IndiaMART से।"
    },
    {
      "i": 3,
      "speaker": "bot",
      "text": "हमारे पास कई अच्छे sellers available हैं जिनसे मैं अभी आपको connect करवाऊंगी।"
    },
    {
      "i": 4,
      "speaker": "bot",
      "text": "बस कुछ details confirm कर दीजिए।"
    },
    {
      "i": 5,
      "speaker": "bot",
      "text": "कितने gram चाहिए होगी आपको?"
    },
    {
      "i": 6,
      "speaker": "caller",
      "text": "चार रुपये किलो है।"
    },
    {
      "i": 7,
      "speaker": "bot",
      "text": "समझ गई।"
    },
    {
      "i": 8,
      "speaker": "bot",
      "text": "पर आपको कितनी quantity चाहिए कृपया आगे बढ़ने से पहले clear कर दीजिए ताकि मैं आपको एक अच्छे seller के साथ connect कर सकूं।"
    },
    {
      "i": 9,
      "speaker": "caller",
      "text": "मुझे आधा kg चाहिए खेती के लिए।"
    },
    {
      "i": 10,
      "speaker": "bot",
      "text": "बहुत बढ़िया।"
    },
    {
      "i": 11,
      "speaker": "bot",
      "text": "मैं देख पा रही हूं आपको variety मोगरा ही चाहिए ना?"
    },
    {
      "i": 12,
      "speaker": "caller",
      "text": "जी Ma'am लाल केसरी जो लाल वाली वो होती Kashmiri।"
    },
    {
      "i": 13,
      "speaker": "bot",
      "text": "ठीक है समझ गई।"
    },
    {
      "i": 14,
      "speaker": "bot",
      "text": "अब वो packaging size के बारे में बात कर लेते हैं।"
    },
    {
      "i": 15,
      "speaker": "bot",
      "text": "आपको कौन सा चाहिए जैसे 1 gram, 0.5 gram या कुछ और?"
    },
    {
      "i": 16,
      "speaker": "caller",
      "text": "one gram."
    },
    {
      "i": 17,
      "speaker": "bot",
      "text": "ठीक है?"
    },
    {
      "i": 18,
      "speaker": "bot",
      "text": "ये आपको मैं seller details WhatsApp पे भेज दूंगी जिनसे आप details और price discuss कर सकते हैं।"
    },
    {
      "i": 19,
      "speaker": "caller",
      "text": "ठीक है।"
    },
    {
      "i": 20,
      "speaker": "bot",
      "text": "IndiaMART चुनने के लिए धन्यवाद।"
    },
    {
      "i": 21,
      "speaker": "bot",
      "text": "आपका दिन शुभ हो।"
    },
    {
      "i": 22,
      "speaker": "caller",
      "text": "आपका।"
    }
  ]
}
